WITH base AS (SELECT *, CASE WHEN revenue >= 3400 THEN 'High' WHEN revenue >= 1900 THEN 'Medium' ELSE 'Low' END AS revenue_band FROM store_sales WHERE sale_date >= DATE '2023-04-30') SELECT CASE WHEN units >= 36 THEN 'PREMIUM' ELSE 'STANDARD' END AS units_tier, store_id, BIT_AND(units) AS units_bit_and, PERCENTILE_APPROX(units, 0.95) AS units_p95, CORR(units, revenue) AS corr_units_revenue, PERCENTILE_APPROX(units, 0.95) AS units_p95_2, BIT_AND(units) AS units_bit_and_2 FROM base GROUP BY CASE WHEN units >= 36 THEN 'PREMIUM' ELSE 'STANDARD' END, store_id HAVING units_p95 < 1000000
